-- Persistent in-app notifications (Command 12). Each row belongs to exactly one account (the recipient) and is
-- removed with its ticket. The message is generated by the server and never contains comment or note text.
CREATE TABLE notifications (
    id                BIGINT       NOT NULL AUTO_INCREMENT,
    recipient_id      BIGINT       NOT NULL,
    notification_type VARCHAR(40)  NOT NULL,
    ticket_id         BIGINT       NULL,
    message           VARCHAR(300) NOT NULL,
    created_at        DATETIME(6)  NOT NULL,
    read_at           DATETIME(6)  NULL,
    CONSTRAINT pk_notifications PRIMARY KEY (id),
    CONSTRAINT fk_notifications_recipient FOREIGN KEY (recipient_id) REFERENCES app_users (id) ON DELETE CASCADE,
    CONSTRAINT fk_notifications_ticket FOREIGN KEY (ticket_id) REFERENCES tickets (id) ON DELETE CASCADE
);
-- Newest-first list and the unread count, both per recipient.
CREATE INDEX idx_notifications_recipient_created ON notifications (recipient_id, created_at);
CREATE INDEX idx_notifications_recipient_read ON notifications (recipient_id, read_at);
